rules.logic:
var sponsoredSection = element;
if (!sponsoredSection) return;

var sidebarRegion = document.querySelector('[data-region="sidebar"] > div');
if (!sidebarRegion) return;

var sidebarContent = sidebarRegion.querySelector('.flex.flex-col.gap-12') || sidebarRegion.firstElementChild;
if (!sidebarContent) return;

// Clone the sponsored content section into the sidebar
var clone = sponsoredSection.cloneNode(true);
clone.style.width = '100%';
sidebarContent.appendChild(clone);

// Hide the original in the main area
sponsoredSection.style.display = 'none';

// Apply grid to the innermost container holding the cards
var inner = element.querySelector('.trc_rbox_div > div') || element.firstElementChild;
if (inner) {
    inner.style.display = 'grid';
    inner.style.gridTemplateColumns = '1fr 1fr';
    inner.style.gap = '12px';
}
